#!/usr/bin/env python3
import os
import sys
import json
from pathlib import Path

def decompress(resharded_dir):
    resharded_path = Path(resharded_dir)

    if not resharded_path.exists():
        raise ValueError(f"Resharded directory does not exist: {resharded_dir}")

    # Read metadata to get original file list
    metadata_file = resharded_path / '__metadata__.json'
    if metadata_file.exists():
        with open(metadata_file, 'r') as f:
            metadata = json.load(f)
        original_files = metadata.get('original_files', [])
    else:
        original_files = []

    # Collect all lines from all data files in all shards
    all_lines = []
    shard_dirs = sorted([d for d in resharded_path.iterdir() if d.is_dir() and d.name.startswith('shard_')])

    for shard_dir in shard_dirs:
        data_files = sorted([f for f in shard_dir.iterdir() if f.is_file() and f.name.startswith('data_')])
        for data_file in data_files:
            with open(data_file, 'r', encoding='utf-8', errors='ignore') as f:
                for line in f:
                    line = line.rstrip('\n')
                    if line:
                        all_lines.append(line)

    # If we have metadata, write back to original filenames
    if original_files:
        # Read original files to count their lines
        original_line_counts = {}
        for orig_file in original_files:
            orig_path = Path(resharded_dir).parent / Path(resharded_dir).name.replace('_reshard', '') / orig_file
            if orig_path.exists():
                with open(orig_path, 'r', encoding='utf-8', errors='ignore') as f:
                    original_line_counts[orig_file] = sum(1 for _ in f)
            else:
                original_line_counts[orig_file] = 0

        # Distribute collected lines back to original files in order
        line_idx = 0
        for orig_file in original_files:
            target_count = original_line_counts.get(orig_file, 0)
            output_file = resharded_path / orig_file

            with open(output_file, 'w', encoding='utf-8') as f:
                for _ in range(target_count):
                    if line_idx < len(all_lines):
                        f.write(all_lines[line_idx] + '\n')
                        line_idx += 1
    else:
        # Fallback: write to c4-mini-*.jsonl files
        num_original_files = 9898
        lines_per_file = len(all_lines) // num_original_files
        remainder = len(all_lines) % num_original_files

        line_idx = 0
        for file_idx in range(num_original_files):
            output_file = resharded_path / f"c4-mini-{file_idx:05d}-of-10000.jsonl"
            num_lines_for_this_file = lines_per_file + (1 if file_idx < remainder else 0)

            with open(output_file, 'w', encoding='utf-8') as f:
                for _ in range(num_lines_for_this_file):
                    if line_idx < len(all_lines):
                        f.write(all_lines[line_idx] + '\n')
                        line_idx += 1

    # Remove shard directories and metadata
    import shutil
    for shard_dir in shard_dirs:
        shutil.rmtree(shard_dir, ignore_errors=True)
    if metadata_file.exists():
        metadata_file.unlink()

def main():
    if len(sys.argv) != 2:
        print(f"Usage: {sys.argv[0]} <resharded_dir>")
        sys.exit(1)

    decompress(sys.argv[1])
    print(f"Decompression complete: {sys.argv[1]}")

if __name__ == "__main__":
    main()
EOF
